// Generated by Qwen
public class Main {

	public static void main(String[] args) {
        // Создаем экземпляры через Builder
        ScreenMain screen = new ScreenMain.Builder()
                .setPosts(new Post[] { new Post("Post1"), new Post("Post2") })
                .setDpi(0.45f)
                .setSize(2000)
                .build();

        ScreenAccount screenAccount = new ScreenAccount.Builder()
                .setPosts(new Post[] { new Post("Post1"), new Post("Post2"), new Post("Post3") })
                .setDpi(0.45f)
                .setSize(2000)
                .build();

        System.out.println("=== Starting ScreenMain, ScreenAccount Lifecycle ===");

        // Выполняем все методы ScreenMain
        System.out.println("\n--- ScreenMain Methods ---");
        screen.onViewCreated(screen.onCreateView());
        screen.onCreateOptionsMenu();
        screen.scrollDown();
        System.out.println("Current Post: " + screen.getCurrentPost());
        screen.showAllPosts();
        
        // Тестируем лайки
        screen.onLike(screen.getCurrentPost());
        screen.onLike(screen.getCurrentPost()); // Двойной лайк
        screen.unlike(screen.getCurrentPost());
        
        // Тестируем скроллинг
        screen.scrollDown();
        screen.scrollUp();
        
        screen.onDestroy();
        screen.showAllPosts();

        // Выполняем все методы ScreenAccount
        System.out.println("\n--- ScreenAccount Methods ---");
        screenAccount.onViewCreated(screenAccount.onCreateView());
        screenAccount.onCreateOptionsMenu();
        screenAccount.scrollDown();
        System.out.println("Current Post: " + screenAccount.getCurrentPost());
        screenAccount.showAllPosts();
        
        // Тестируем лайки
        screenAccount.onLike(screenAccount.getCurrentPost());
        screenAccount.onLike(screenAccount.getCurrentPost()); // Двойной лайк
        screenAccount.unlike(screenAccount.getCurrentPost());
        
        // Тестируем скроллинг
        screenAccount.scrollDown();
        screenAccount.scrollUp();
        screenAccount.scrollDown();
        
        screenAccount.onDestroy();
        screenAccount.showAllPosts();
        
        System.out.println("\n=== Lifecycle Completed ===");
	}

}
